import{_ as i,o as e,c as l,ag as o}from"./chunks/framework.QfQ7DfGu.js";const m=JSON.parse('{"title":"交流论坛","description":"","frontmatter":{"title":"交流论坛","outline":"deep"},"headers":[],"relativePath":"misc/loong64-form.md","filePath":"misc/loong64-form.md"}'),n={name:"misc/loong64-form.md"};function t(s,a,r,c,p,h){return e(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="龙架构技术交流论坛" tabindex="-1">龙架构技术交流论坛 <a class="header-anchor" href="#龙架构技术交流论坛" aria-label="Permalink to &quot;龙架构技术交流论坛&quot;">​</a></h1><hr><div class="form"><p>此处收集一些面向龙架构的技术交流论坛，汇总如下：</p><section><h2 id="龙芯爱好者论坛" tabindex="-1">龙芯爱好者论坛 <a class="header-anchor" href="#龙芯爱好者论坛" aria-label="Permalink to &quot;龙芯爱好者论坛&quot;">​</a></h2><div class="dlmi-actions"><a class="dlmi-chip dlmi-chip--link" href="https://www.loongbbs.cn/" target="_blank" rel="noopener noreferrer"><span class="dlmi-chip__text">点击跳转</span></a></div><p>龙芯爱好者论坛，旨在为想要在龙架构生态中进行软硬件开发的工程师们提供帮助与支持，包含有：</p><ul><li>操作系统</li><li>龙架构教学与竞赛</li><li>硬件与固件</li><li>开源项目交流</li></ul><p>以及其他方面的讨论交流。</p></section><section><h2 id="龙芯爱好者社区" tabindex="-1">龙芯爱好者社区 <a class="header-anchor" href="#龙芯爱好者社区" aria-label="Permalink to &quot;龙芯爱好者社区&quot;">​</a></h2><div class="dlmi-actions"><a class="dlmi-chip dlmi-chip--link" href="https://loongfans.cn/" target="_blank" rel="noopener noreferrer"><span class="dlmi-chip__text">点击跳转</span></a></div><p>龙芯爱好者社区是一个由第三方爱好者、行业人员与学生组成的，致力于龙芯（龙架构）软硬件生态建设的互联网社区。</p><p>其包含的内容有：</p><ul><li>新手资源。包含有踩坑指南、开发指南等入门教程。</li><li>数据材料。包含有芯片规格、产品规格、软硬件兼容数据等信息。</li><li>社区资源。包含有交流论坛、技术分享等内容。</li></ul></section><section><h2 id="龙架构悬赏与实习机会" tabindex="-1">龙架构悬赏与实习机会 <a class="header-anchor" href="#龙架构悬赏与实习机会" aria-label="Permalink to &quot;龙架构悬赏与实习机会&quot;">​</a></h2><div class="dlmi-actions"><a class="dlmi-chip dlmi-chip--link" href="https://loongfans.cn/jobs" target="_blank" rel="noopener noreferrer"><span class="dlmi-chip__text">点击跳转</span></a></div><p>社区悬赏网站。</p><p>这里公布有社区所需求的适配、研发项目，并有项目完成的相应奖励。</p><p>网站经常公布社区实习机会，有需求的同学可以主动联系。</p></section><section><h2 id="loong64" tabindex="-1">loong64 <a class="header-anchor" href="#loong64" aria-label="Permalink to &quot;loong64&quot;">​</a></h2><div class="dlmi-actions"><a class="dlmi-chip dlmi-chip--link" href="https://github.com/loong64" target="_blank" rel="noopener noreferrer"><span class="dlmi-chip__text">点击跳转</span></a></div><p>LoongArch64 生态分享与讨论区，包含有：</p><ul><li>tensorflow LoongArch64 支持</li><li>llama LoongArch64 支持</li><li>pytorch LoongArch64 支持</li></ul><p>以及其他开源应用</p></section><section><h2 id="咱龙了吗" tabindex="-1">咱龙了吗 <a class="header-anchor" href="#咱龙了吗" aria-label="Permalink to &quot;咱龙了吗&quot;">​</a></h2><div class="dlmi-actions"><a class="dlmi-chip dlmi-chip--link" href="https://areweloongyet.com/docs/intro" target="_blank" rel="noopener noreferrer"><span class="dlmi-chip__text">点击跳转</span></a></div><p>这里是社区建立的一个关于龙架构的咨询网站，你可以跟踪一些开源软件的上游项目进展。</p><p>除此之外，《咱龙了吗？》项目也收集维护、自行撰写了一些围绕龙架构的其他阅读材料。</p><p>网站完全由社区爱心人士、龙芯路线的同情者维护，源代码托管在 GitHub 上，由社区爱好者随时更新。</p></section><section><h2 id="龙架构双周会" tabindex="-1">龙架构双周会 <a class="header-anchor" href="#龙架构双周会" aria-label="Permalink to &quot;龙架构双周会&quot;">​</a></h2><div class="dlmi-actions"><a class="dlmi-chip dlmi-chip--link" href="https://loongfans.cn/biweekly" target="_blank" rel="noopener noreferrer"><span class="dlmi-chip__text">点击跳转</span></a></div><p>龙架构双周会是由龙芯爱好者组织的社区会议，会议议程包括针对上游及各 Linux 发行版及其他系统项目的开发进展报告、社区事务报告，以及贡献者讨论及问答环节。</p><p>龙架构双周会一般于 UTC+8 时区的每两周周日 14:00 在腾讯会议举办，原则上避开中国大陆预期出行较多的法定假期（如春节、国庆等）与调休工作日。</p><p>会议进程于 Bilibili @龙芯爱好者社区 账号同步直播，亦时有安排线下活动。</p></section><section><h2 id="龙架构的哔哩哔哩" tabindex="-1">龙架构的哔哩哔哩 <a class="header-anchor" href="#龙架构的哔哩哔哩" aria-label="Permalink to &quot;龙架构的哔哩哔哩&quot;">​</a></h2><div class="dlmi-actions"><a class="dlmi-chip dlmi-chip--link" href="https://space.bilibili.com/70360929" target="_blank" rel="noopener noreferrer"><span class="dlmi-chip__text">点击跳转</span></a></div><p>龙芯爱好者社区是由第三方爱好者、行业人员与学生组成的，致力于龙芯（龙架构）软硬件生态建设的互联网社区。</p><p>在这里，可以看到很多有趣好玩的东西！</p></section></div>',3)])])}const _=i(n,[["render",t]]);export{m as __pageData,_ as default};
